#pragma once
#include "core/campaign_node_completion.hpp"
namespace rolo {
enum class FrontEndStep{FadeBlack,LoadPalette,ClearSprites,PrepareFont,ResetPlanes,ClearForeground,ClearBackground,Diagnostics,PrintText,FadeIn,DebugMenu,CompleteNode,ResetScroll,LoadPlanes,ClearLookup,ResetActorPools,ResetGraphics,CreateWorldActors,InitializeWorldCamera,ForegroundTerrain,BackgroundTerrain,ForegroundScroll,BackgroundScroll,CopyParents,InitializeHud,WorldPalette,Music,PrepareActors,PublishGraphics,WorldInput,BuildActive,MoveBunny,WorldPaletteCycle,Animate,TileAnimation,RenderActors,CompletedMarkers,WorldCamera,AdmitLevel};
struct FrontEndState{std::uint32_t frame_hook{},main_state{},text{};std::uint16_t selector{},display{},plane{},x{},y{},attributes{},selection{},shift_x{},shift_y{},pattern{};std::uint8_t complete{},paused{},palette_wait{},palette_count{};std::array<std::uint8_t,4>input{};};
struct FrontEndServices{virtual ~FrontEndServices()=default;virtual void step(FrontEndStep)=0;virtual void control(std::uint16_t)=0;virtual void music(std::uint16_t,std::uint16_t)=0;};
inline void run_debug_front_end(FrontEndState&s,FrontEndServices&v){if(s.frame_hook==0x19ba){v.step(FrontEndStep::DebugMenu);return;}v.step(FrontEndStep::FadeBlack);s.selector=65534;v.step(FrontEndStep::LoadPalette);s.frame_hook=0x19ba;for(auto op:{FrontEndStep::ClearSprites,FrontEndStep::PrepareFont,FrontEndStep::ResetPlanes,FrontEndStep::ClearForeground,FrontEndStep::ClearBackground})v.step(op);s.plane=0xc000;v.step(FrontEndStep::Diagnostics);s.plane=0xc000;s.text=0x58d1;s.x=7;s.y=0;s.attributes=0;v.step(FrontEndStep::PrintText);s.text=0x5925;s.x=10;s.y=7;s.attributes=0x2000;v.step(FrontEndStep::PrintText);s.selection=0;s.selector=65534;v.step(FrontEndStep::FadeIn);}
inline void run_world_front_end(FrontEndState&s,FrontEndServices&v){
 if(s.frame_hook!=0x1a6e){if(s.complete){s.main_state=0x9be2;return;}s.frame_hook=0x1a6e;v.step(FrontEndStep::CompleteNode);s.selector=0;v.step(FrontEndStep::FadeBlack);s.display&=0xffbf;v.control(s.display);v.step(FrontEndStep::ResetScroll);s.shift_x=s.shift_y=0;for(auto op:{FrontEndStep::PrepareFont,FrontEndStep::ResetPlanes,FrontEndStep::ClearForeground,FrontEndStep::ClearBackground})v.step(op);s.pattern=1;for(auto op:{FrontEndStep::LoadPlanes,FrontEndStep::ClearLookup,FrontEndStep::ResetActorPools,FrontEndStep::ResetGraphics,FrontEndStep::CreateWorldActors,FrontEndStep::InitializeWorldCamera,FrontEndStep::ForegroundTerrain,FrontEndStep::BackgroundTerrain,FrontEndStep::ForegroundScroll,FrontEndStep::BackgroundScroll,FrontEndStep::CopyParents,FrontEndStep::FadeIn})v.step(op);s.paused=0;v.step(FrontEndStep::InitializeHud);v.step(FrontEndStep::WorldPalette);s.palette_wait=0;s.palette_count=6;v.music(16,65535);s.display|=64;v.control(s.display);return;}
 for(auto op:{FrontEndStep::PrepareActors,FrontEndStep::PublishGraphics,FrontEndStep::ForegroundScroll,FrontEndStep::BackgroundScroll,FrontEndStep::WorldInput,FrontEndStep::BuildActive,FrontEndStep::MoveBunny,FrontEndStep::WorldPaletteCycle,FrontEndStep::Animate,FrontEndStep::TileAnimation,FrontEndStep::RenderActors,FrontEndStep::PublishGraphics,FrontEndStep::CompletedMarkers,FrontEndStep::WorldCamera,FrontEndStep::ForegroundTerrain,FrontEndStep::BackgroundTerrain})v.step(op);
 if(!s.paused&&((s.input[1]|s.input[2]|s.input[3])&1)){v.step(FrontEndStep::AdmitLevel);return;}if(s.input[0]&1)s.paused=std::uint8_t(~s.paused);
}
enum class MenuCheatResult{None,Released,Restart,ReturnToMenu};
struct MenuCheatServices{virtual ~MenuCheatServices()=default;virtual std::uint8_t sample_input()=0;virtual void refresh_menu()=0;virtual void restart_platform()=0;};
inline MenuCheatResult run_original_menu_cheat(std::uint8_t last,std::uint8_t pressed,CampaignResetState&s,MenuCheatServices&v){if(last!=101)return MenuCheatResult::None;switch(pressed&112){case 112:for(;;){const auto input=v.sample_input();if(!input)return MenuCheatResult::Released;if((input&112)==112)break;}while(v.sample_input()){}v.restart_platform();return MenuCheatResult::Restart;case 96:reset_campaign_score(s);v.refresh_menu();return MenuCheatResult::ReturnToMenu;case 80:reset_score_threshold(s.awards);v.refresh_menu();return MenuCheatResult::ReturnToMenu;default:return MenuCheatResult::None;}}
}
